<?php require __DIR__.'/app/bootstrap.php'; $slug=$_GET['slug']??''; $s=db()->prepare('SELECT * FROM categories WHERE slug=? AND is_active=1');$s->execute([$slug]);$category=$s->fetch();if(!$category){http_response_code(404);exit('Category not found');}$s=db()->prepare("SELECT * FROM products WHERE category_id=? AND status='active' ORDER BY created_at DESC");$s->execute([$category['id']]);$products=$s->fetchAll();$pageTitle=$category['name'].' — NEXT TECH';require __DIR__.'/includes/header.php'; ?><section class="page-intro"><span class="eyebrow">CATEGORY</span><h1><?=e($category['name'])?></h1><p><?=e($category['description'])?></p></section><div class="product-grid"><?php foreach($products as $p): ?><article class="product-card"><a href="<?=e(url('product.php?slug='.rawurlencode($p['slug'])))?>"><div class="product-image"><?php if($p['image']): ?><img src="<?=e(url('uploads/products/'.$p['image']))?>" alt="<?=e($p['name'])?>"><?php else: ?><span>◇</span><?php endif; ?></div><h3><?=e($p['name'])?></h3></a><p class="price"><?=money($p['price'])?></p></article><?php endforeach; ?><?php if(!$products): ?><p class="empty-state">No products in this category yet.</p><?php endif; ?></div><?php require __DIR__.'/includes/footer.php'; ?>
